package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Checks every pasted line before any is added: its person must be on the sheet (names compared as names are, case
 *  and outer spaces ignored) and its claim must keep the rules of adding a claim (see ClaimRules), its reference
 *  not repeating one on an earlier line (case ignored). Any failing line refuses the whole paste. */
public class CheckPastedClaims {
    public void check(@PathVariable("sheetId") String sheetId, @Val PastedLines pasted, PersonRepository people,
            SettingRepository settings, PeriodRepository periods, ClaimRepository claims, HolidayRepository holidays,
            Out<PastedClaims> checked)
            throws InvalidClaimException {
        String sheet = sheetId.trim();
        List<PastedClaim> all = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (PastedLine line : pasted.lines()) {
            Person person = people.findByName(sheet, line.name());
            if (person == null) {
                throw new InvalidClaimException("No person named " + line.name() + " on the sheet");
            }
            String ref = line.values().ref();
            if (ref != null && !refs.add(ClaimValues.refKey(ref))) {
                throw new InvalidClaimException("The reference " + ref + " is pasted more than once");
            }
            all.add(new PastedClaim(person, line.values(), ClaimRules.check(person, line.values(), settings, periods, claims, holidays)));
        }
        checked.set(new PastedClaims(all));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey } from '../claims/claims';
import { peopleKey } from '../people/people';

type Result = { added: number };

/** The paste box: lines of name,amount,date,note (the note may hold commas and may be absent; a blank date is the
 *  sheet's entry date, else its today) each add a DRAFT claim, in order, for the person with the name; a note ending in ` #<reference>` gives the claim that
 *  external reference (not part of the note). The server checks every line by the
 *  claim form's rules first (a reference repeated within the paste counts as already used): one failing line refuses the paste and adds nothing. Shows how many were added; the
 *  count is cleared while a new press runs. */
function PasteClaims({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const submit = useSubmitOnce();
  const paste = useMutation({
    mutationFn: (t: string) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/paste-claims`, { text: t, by: user }),
    onSuccess: () => {
      setText('');
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        paste.reset();
        paste.mutate(text);
      }}
    >
      <label>
        Paste claims (name,amount,date,note per line)
        <br />
        <textarea
          data-testid="paste-claims"
          rows={4}
          cols={50}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            paste.reset();
          }}
        />
      </label>
      <br />
      <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
        Add draft claims
      </button>
      {paste.isSuccess && (
        <>
          {' '}
          Added <span data-testid="paste-added">{paste.data.added}</span>
        </>
      )}
      {paste.isError && (
        <span data-testid="paste-error">
          {' '}
          Nothing was added: every line must name a person on the sheet and keep the claim form's rules, with no reference already used on the sheet or repeated in the paste.
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPage.fill({ order: 24, Component: PasteClaims });

