package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed (the amounts of their claims that count added up, leaving out corrections; a person's OPEN or PENDING claims dated within a hold of theirs, or any once their retirement date is reached, not bound by a statement, do not, nor do deferred claims) and
 * due-total (the figures of those claims, each with its late charge, added up; n/a when their grade has no rate today and no counting claim
 * has a figure, kept or at the grade in force on its date; at most the sheet's cap), overdue-total (the figures, late charge included, of those claims that are overdue — open, their due-by plus
 * their grace (see LateCharge#lateFrom) before today — added up, skipping n/a; not capped), and the sheet's claimed-total, due-total and overdue-total (everyone's added up, skipping n/a; the due-total and
 * overdue-total leave out the single highest and the single lowest figure when three or more people have one).
 *
 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
 * person whose figures (claimed, due-total or overdue-total) moved (a person new to the sheet counts as moved), then
 * TOTALS when any of the sheet's three totals moved ({@link #record}), then ALERT, in list order, for every person
 * whose due-total went from at or below the sheet's alert threshold (or no due-total: n/a, or new to the sheet) to
 * above it (none while the threshold is off).
 */
@Service
public class Rollup {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Every person's figures on the sheet now, in list order (see PersonRepository#list). */
    public RollupBefore take(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> all = claims.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean figured = false;
            for (Claim c : all) {
                if (c.personId() != person.id() || !ClaimDue.countsLive(c, person, today)) {
                    continue;
                }
                if (c.corrects() == null) {
                    claimed = claimed.add(c.amount());
                }
                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, late.rounding()), settings.floor(sheetId, c.date()));
                figured |= figure != null;
                if (figure != null) {
                    due = due.add(figure);
                    if (ClaimDue.isOpen(c) && late.lateFrom(c).isBefore(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a"
                    : SettingRepository.capped(due, cap).toPlainString();
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal,
                    overdue.toPlainString()));
        }
        return new RollupBefore(figures);
    }

    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
    public void record(String sheetId, String by, RollupBefore before) {
        Map<Long, Figures> after = take(sheetId).figures();
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.figures().get(e.getKey());
            Figures now = e.getValue();
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                        + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        String claimedBefore = claimedTotal(before.figures());
        String dueBefore = dueTotal(before.figures());
        String claimedAfter = claimedTotal(after);
        String dueAfter = dueTotal(after);
        String overdueBefore = overdueTotal(before.figures());
        String overdueAfter = overdueTotal(after);
        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)
                || !Objects.equals(overdueBefore, overdueAfter)) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
                    + dueAfter + " overdue-total=" + overdueAfter);
        }
        alert(sheetId, by, before.figures(), after);
    }

    /** Writes ALERT, in list order, for every person whose due-total went from at or below the sheet's alert threshold
     *  (or no due-total) before to above it now. */
    private void alert(String sheetId, String by, Map<Long, Figures> before, Map<Long, Figures> after) {
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold == null) {
            return;
        }
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.get(e.getKey());
            Figures now = e.getValue();
            if (above(now, threshold) && (was == null || !above(was, threshold))) {
                audit.record("ALERT sheet=" + sheetId + " by=" + by + " name=" + now.name() + " due-total="
                        + now.dueTotal());
            }
        }
    }

    private static boolean above(Figures figures, BigDecimal threshold) {
        return !figures.dueTotal().equals("n/a") && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
    }

    /** Writes ROLLUP for every person on the sheet, in list order, then TOTALS, then ALERT for those above the alert
     *  threshold: the figures of a sheet just made. */
    public void recordAll(String sheetId, String by) {
        Map<Long, Figures> now = take(sheetId).figures();
        for (Figures f : now.values()) {
            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + f.name() + " claimed=" + f.claimed()
                    + " due-total=" + f.dueTotal() + " overdue-total=" + f.overdueTotal());
        }
        audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedTotal(now) + " due-total="
                + dueTotal(now) + " overdue-total=" + overdueTotal(now));
        alert(sheetId, by, Map.of(), now);
    }

    private static String claimedTotal(Map<Long, Figures> figures) {
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
public final class ClaimRules {

    private ClaimRules() {
    }

    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
     *  correct a SETTLED claim (see Corrections), or a reference already used on the sheet (see checkRef). */
    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
        int terms = terms(person, date, settings);
        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
        if (periods.closedOn(person.sheetId(), dueBy)) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        checkRef(person.sheetId(), values, null, claims);
        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy, terms);
    }

    /** Refuses a reference another claim of the sheet already has, comparing without regard to case; {@code self} is the
     *  claim being edited (null for an add), whose own reference does not count. */
    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
        }
    }

    /** The due-by a claim of the person dated the date is fixed with as it is added: the terms-th business day after its date (see
     *  HolidayRepository.businessDaysAfter), the terms being the person's own, else those of their grade in force on that date (the
     *  holidays on the sheet now decide; one added later works it out again, see ClaimRepository#refixDueBys). */
    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date, terms(person, date, settings));
    }

    /** The terms a claim of the person dated the date is fixed with: the person's own, else those of their grade in force on
     *  that date. The claim keeps them, so its due-by can be worked out again when a holiday is added (see ClaimRepository#refixDueBys). */
    public static int terms(Person person, LocalDate date, SettingRepository settings) {
        return settings.terms(person.sheetId(), person.terms(), person.gradeOn(date), date);
    }

    /** Whether opening the claim would take its person past the cap of the period its due-by falls in: they already have
     *  that many OPEN or PENDING claims in it (a period with no cap, or no period: never). */
    public static boolean overCap(Claim claim, PeriodRepository periods, ClaimRepository claims) {
        Period period = periods.containing(claim.sheetId(), claim.dueBy());
        return period != null && period.cap() != null
                && claims.heldIn(claim.sheetId(), claim.personId(), period.from(), period.to()) >= period.cap();
    }

    /** A claim's date, the number it corrects (null when none), its due-by and the terms it was fixed with, once its rules are kept. */
    public record Checked(LocalDate date, String corrects, LocalDate dueBy, int terms) {
    }
}
